function openEntry(text=''){
 if(listening||holding)cancelVoice();drafts=[];parseErrors=[];$('#dictation').value=text;$('#drafts').innerHTML='';$('#parseErrors').textContent='';$('#saveButton').hidden=true;$('#sheetTitle').textContent='Что запишем?';if(!$('#entryDialog').open)$('#entryDialog').showModal();if(text)parseInput();else $('#dictation').focus();translateUI();
}
$('#textEntry').onclick=()=>openEntry();$('#closeEntry').onclick=()=>$('#entryDialog').close();
$('#dictation').oninput=()=>{drafts=[];parseErrors=[];$('#drafts').innerHTML='';$('#saveButton').hidden=true;$('#parseErrors').textContent='';};
function parseInput(){const r=E.parse($('#dictation').value,new Date(),state.entries,state,voiceAccount);drafts=r.entries;parseErrors=r.errors;$('#parseErrors').innerHTML=r.errors.map(e=>`<p class="warn">${esc(e)}</p>`).join('')+(r.errors.length&&drafts.length?'<p class="warn">Исправьте неразобранные части текста перед сохранением.</p>':'');renderDrafts();}
$('#parseButton').onclick=parseInput;
function installmentRows(plan,currency){
 return plan.map((part,i)=>`<li><span>${esc(part.date.split('-').reverse().join('.'))} · ${i===0?'расход':'платёж'}</span><strong>${money(part.amount,currency)}</strong></li>`).join('');
}
function renderDrafts(){
 $('#sheetTitle').textContent=drafts.length?'Проверим и запишем':'Что запишем?';
 $('#drafts').innerHTML=drafts.map((e,i)=>{const a=account(e.account),saving=e.type==='saving',installment=e.installmentTotal!==undefined;
 const plan=installment&&e.installmentTotal>=4&&e.date?E.installmentPlan(e.installmentTotal,e.date):[];
 return `<div class="draft" data-index="${i}"><div class="draft-top"><label>Название<input data-field="title" required maxlength="300" value="${esc(e.title)}"></label><label>${installment?'Полная сумма':'Сумма'}, ${a.currency}<input data-field="${installment?'installmentTotal':'amount'}" type="number" min="${installment?'0.04':'0.01'}" max="10000000000" step="0.01" required value="${(e.installmentTotal??e.amount)/100}"></label></div><div class="draft-bottom"><label>Тип<select data-field="type" ${installment?'disabled':''}><option value="expense" ${e.type==='expense'?'selected':''}>Расход</option><option value="income" ${e.type==='income'?'selected':''}>Доход</option><option value="saving" ${saving?'selected':''} >Накопления</option></select></label><label>Счёт<select data-field="account">${accountOptions(e.account,saving?state.goals.find(g=>g.id===e.goalId)?.currency??null:null)}</select></label>${saving?`<label>Цель<select data-field="goalId"><option value="" ${!e.goalId?'selected':''}>Накопления без цели</option>${state.goals.filter(g=>g.currency===a.currency).map(g=>`<option value="${esc(g.id)}" ${g.id===e.goalId?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`:`<label>Категория<select data-field="category">${categoryOptions(e.type,e.category)}</select></label>`}<label>Дата<input data-field="date" type="date" required value="${e.date}"></label></div>${installment?`<div class="draft-installments"><strong>Долями · 4 платежа</strong><ol data-installment-plan>${installmentRows(plan,a.currency)}</ol></div>`:''}<div class="draft-actions"><span class="muted tiny">${saving?'Со счёта в цель · не расход':'Проверьте сумму, категорию и счёт'}</span><button data-remove="${i}">Убрать</button></div></div>`;}).join('');
 $('#saveButton').hidden=!drafts.length;$('#saveButton').disabled=!!parseErrors.length;$('#saveButton').textContent=drafts.length===1?'Сохранить запись':`Сохранить записи · ${drafts.length}`;translateUI();
}
$('#drafts').oninput=e=>{const field=e.target.dataset.field;if(!field)return;const draft=drafts[Number(e.target.closest('[data-index]').dataset.index)];draft[field]=['amount','installmentTotal'].includes(field)?cents(e.target.value):e.target.value;if(field==='category')draft.categoryChosen=true;
 if(draft.installmentTotal!==undefined&&['installmentTotal','date'].includes(field)){
  const plan=e.target.validity.valid&&draft.installmentTotal>=4&&draft.date?E.installmentPlan(draft.installmentTotal,draft.date):[];
  e.target.closest('.draft').querySelector('[data-installment-plan]').innerHTML=installmentRows(plan,account(draft.account).currency);
 }
 if(field==='type'){if(draft.type==='saving'){draft.goalId=null;delete draft.refundOf;delete draft.category;delete draft.categoryChosen;}else{draft.category=(draft.type==='income'?state.incomeCategories:state.categories)[0];delete draft.goalId;if(draft.type!=='income')delete draft.refundOf;}renderDrafts();}
 if(field==='account'||field==='goalId')renderDrafts();
};
$('#drafts').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){drafts.splice(Number(b.dataset.remove),1);renderDrafts();}};
$('#saveButton').onclick=()=>{if(!drafts.length||parseErrors.length)return;for(const input of $('#drafts').querySelectorAll('input'))if(!input.reportValidity())return;let next,added;try{({next,added}=E.saveDrafts(state,drafts));}catch(error){notify(error.message);return;}
 if(added.some(e=>e.type==='saving'&&E.balance(next,e.account)<0)&&!confirm('Пополнение цели сделает остаток счёта отрицательным. Продолжить?'))return;
 if(!persist(next))return;drafts=[];$('#entryDialog').close();refreshAccounts();renderHomeReminders();if(page!=='home')render();const alerts=[];for(const [c,ls] of Object.entries(state.limits))for(const [cat,limit] of Object.entries(ls))if(added.some(e=>e.type==='expense'&&e.category===cat&&entryCurrency(e)===c&&e.date.startsWith(currentMonth()))&&spending(cat,c)>=limit*.8)alerts.push(cat+' · '+c+': '+(spending(cat,c)>=limit?'лимит достигнут':'осталось '+money(limit-spending(cat,c),c)));notify(alerts.length?'Записано. '+alerts.join('. '):added.some(e=>e.type==='saving')?'Накопления пополнены. В расходы не включены.':'Записано. Всё на своих местах.',true);
};
let recognition;
function resetVoiceUI(){listening=false;document.body.classList.remove('listening','holding');$('#mic').setAttribute('aria-pressed','false');$('#mic').disabled=false;$('#voiceStatus').textContent='';$('#voiceHint').textContent='';}
recognition=MonoVoice.create({Recognition:window.MonoNative?.Recognition||window.SpeechRecognition||window.webkitSpeechRecognition,secure:!!window.MonoNative||window.isSecureContext,onState:phase=>{listening=phase!=='idle';document.body.classList.toggle('listening',listening);$('#mic').setAttribute('aria-pressed',holding?'true':'false');$('#mic').disabled=phase==='stopping'||phase==='finishing';if(phase==='idle'){holding=false;resetVoiceUI();}else{$('#voiceStatus').textContent=phase==='starting'?'Подключаю микрофон…':phase==='stopping'?'Завершаю диктовку…':phase==='finishing'?'Сеанс завершается…':'Слушаю. Можно не спешить.';$('#voiceHint').textContent=phase==='starting'?'Если появится запрос — разрешите доступ.':'Отпустите кнопку, когда закончите.';}},onProgress:text=>{if(text)$('#voiceHint').textContent=text;},onResult:text=>{holding=false;resetVoiceUI();openEntry(text);},onFailure:error=>{holding=false;document.body.classList.remove('holding');$('#voiceErrorCode').textContent=error.code;$('#voiceErrorMessage').textContent=error.message;$('#voiceErrorDetail').textContent=error.detail||'Нет дополнительного сообщения.';$('#micTestStatus').textContent='';if(!$('#voiceErrorDialog').open)$('#voiceErrorDialog').showModal();}});
function startHold(){if(holding||listening||$('#lockDialog').open)return;holding=true;document.body.classList.add('holding');$('#mic').setAttribute('aria-pressed','true');recognition.start({hold:true});}
function endHold(){if(!holding)return;holding=false;document.body.classList.remove('holding');recognition.stop();}
function cancelVoice(){holding=false;recognition.abort();resetVoiceUI();}
$('#mic').onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();$('#mic').setPointerCapture?.(e.pointerId);startHold();};
$('#mic').onpointerup=e=>{e.preventDefault();endHold();};$('#mic').onpointercancel=()=>cancelVoice();$('#mic').onlostpointercapture=()=>{if(holding)endHold();};$('#mic').oncontextmenu=e=>e.preventDefault();
$('#mic').onkeydown=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(!e.repeat)startHold();}};$('#mic').onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();endHold();}};$('#mic').onblur=()=>{if(holding)endHold();};
$('#closeVoiceError').onclick=()=>$('#voiceErrorDialog').close();$('#keyboardVoice').onclick=()=>{$('#voiceErrorDialog').close();openEntry();$('#keyboardHint').hidden=false;};
$('#testMic').onclick=async()=>{if(window.MonoNative){MonoNative.openSettings();return;}const b=$('#testMic');b.disabled=true;let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});$('#micTestStatus').textContent='Микрофон доступен. Распознавание речи использует отдельное разрешение.';}catch(error){$('#micTestStatus').textContent='Не удалось получить доступ: '+error.name;}finally{stream?.getTracks().forEach(t=>t.stop());b.disabled=false;}};
const tourSteps=[
 {page:'home',target:'.voice-zone',title:'Просто скажите',text:'Зажмите микрофон. Назовите траты — моно распределит их по категориям.'},
 {page:'history',target:'#operationCards',title:'Всё перед глазами',text:'Доходы и расходы. Нажмите на карточку, чтобы увидеть подробности.'},
 {page:'menu',target:'.menu-grid',title:'Под себя',text:'Добавляйте счета и цели. Устанавливайте лимиты.'}
];
function startTour(){if($('#lockDialog').open)return;cancelVoice();tourActive=true;tourStep=0;chartExpanded=false;showTourStep();if(!$('#onboarding').open)$('#onboarding').showModal();requestAnimationFrame(positionTour);}
function showTourStep(){const step=tourSteps[tourStep];navigate(step.page);$('#tourTitle').textContent=step.title;$('#tourText').textContent=step.text;$('#tourCount').textContent=`0${tourStep+1} / 03`;$('#tourBack').hidden=tourStep===0;$('#finishWelcome').textContent=tourStep===2?'Готово ✓':'Далее ↗';$$('.tour-dots i').forEach((dot,i)=>dot.classList.toggle('active',i===tourStep));$('.tour-card').getAnimations().forEach(a=>a.cancel());if(!reducedMotion())$('.tour-card').animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'ease-out'});positionTour();}
function positionTour(){if(!tourActive)return;const target=$(tourSteps[tourStep].target);if(!target)return;const spotlight=$('#tourFocus');spotlight.style.borderRadius=tourStep===0?'50%':'25px';$('.tour-top').style.maskImage='';$('.tour-top').style.webkitMaskImage='';spotlight.hidden=tourStep===2;if(tourStep===2){Object.assign($('.tour-top').style,{left:'0px',top:'0px',width:innerWidth+'px',height:innerHeight+'px'});for(const side of ['.tour-left','.tour-right','.tour-bottom'])Object.assign($(side).style,{width:'0px',height:'0px'});const card=$('.tour-card'),width=Math.min(350,innerWidth-32);Object.assign(card.style,{width:width+'px',left:(innerWidth-width)/2+'px',top:Math.max(18,(innerHeight-card.offsetHeight)/2)+'px'});return;}const r=target.getBoundingClientRect(),transform=getComputedStyle($('.app')).transform,offset=transform==='none'?0:new DOMMatrix(transform).m41,pad=10,w=innerWidth,h=innerHeight,x=Math.max(8,r.left-offset-pad),y=Math.max(8,r.top-pad),right=Math.min(w-8,r.right-offset+pad),bottom=Math.min(h-8,r.bottom+pad);const focus=$('#tourFocus');Object.assign(focus.style,{left:x+'px',top:y+'px',width:(right-x)+'px',height:(bottom-y)+'px'});
 const rect=(selector,left,top,width,height)=>Object.assign($(selector).style,{left:left+'px',top:top+'px',width:Math.max(0,width)+'px',height:Math.max(0,height)+'px'});
 rect('.tour-top',0,0,w,y);rect('.tour-left',0,y,x,bottom-y);rect('.tour-right',right,y,w-right,bottom-y);rect('.tour-bottom',0,bottom,w,h-bottom);
 if(tourStep===0){const radius=Math.min(right-x,bottom-y)/2,mask=`radial-gradient(circle ${radius}px at ${(x+right)/2}px ${(y+bottom)/2}px,transparent calc(100% - 1px),#000 100%)`;rect('.tour-top',0,0,w,h);$('.tour-top').style.maskImage=mask;$('.tour-top').style.webkitMaskImage=mask;for(const side of ['.tour-left','.tour-right','.tour-bottom'])rect(side,0,0,0,0);}

 const card=$('.tour-card'),ch=card.offsetHeight||185,cw=Math.min(350,w-32);let cy=bottom+20;if(cy+ch>h-18)cy=Math.max(18,y-ch-20);if(cy+ch>h-18)cy=h-ch-18;Object.assign(card.style,{width:cw+'px',left:(w-cw)/2+'px',top:cy+'px'});
}
