$('#finishWelcome').onclick=()=>{if(tourStep<2){tourStep++;showTourStep();}else finishWelcome();};$('#tourBack').onclick=()=>{if(tourStep>0){tourStep--;showTourStep();}};$('#skipWelcome').onclick=finishWelcome;$('#onboarding').addEventListener('cancel',e=>{e.preventDefault();finishWelcome();});$('#helpButton').onclick=()=>navigate('profile');
window.addEventListener('resize',positionTour);window.addEventListener('scroll',positionTour,{passive:true});
function toggleChart(type,button){MonoCharts.open(type,button);}

async function verifyPin(pin){return MonoPIN.verify(pin,lockRecord);}
function bindPinInputs(container){container.querySelectorAll('[data-pin-limit]').forEach(input=>{input.oninput=()=>{input.value=MonoPIN.clean(input.value,Number(input.dataset.pinLimit));};});}
function setupLock(disable=false){
 if(!crypto.subtle){notify('Код доступа доступен по защищённому адресу HTTPS.');return;}
 if(disable&&!lockRecord)return;
 if(!disable&&!window.MonoAccess?.canSetPIN()){notify('Код станет доступен после оплаты подписки и привязки Telegram. Подключение готовится.');return;}
 const limit=MonoPIN.limit(lockRecord),pattern=limit===4?'[0-9]{4}':'[0-9]{4,12}';
 actionDialog(disable?'Отключить код':lockRecord?'Изменить код':'Новый код',`<form class="pin-form">${lockRecord?`<label class="field">Текущий код<input name="current" type="password" inputmode="numeric" pattern="${pattern}" maxlength="${limit}" data-pin-limit="${limit}" required autocomplete="off"></label>`:''}${disable?'<p class="muted">Подтвердите текущий код, чтобы отключить блокировку.</p>':'<label class="field">Новый код · 4 цифры<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" data-pin-limit="4" required autocomplete="new-password"></label><label class="field">Повторите код<input name="repeat" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" data-pin-limit="4" required autocomplete="new-password"></label><p class="muted tiny">Запомните код. Восстановление не подключено.</p>'}<p class="form-error" role="alert" hidden></p><button class="primary">${disable?'Отключить код':'Сохранить код'}</button></form>`,async(f,form)=>{
  const b=form.querySelector('button'),error=form.querySelector('.form-error');b.disabled=true;error.hidden=true;
  try{
   if(lockRecord&&!await verifyPin(f.get('current')))throw Error('Текущий код неверный.');
   if(disable){localStorage.removeItem('mono-lock');lockRecord=null;}
   else{if(f.get('pin')!==f.get('repeat'))throw Error('Коды не совпадают.');const record=await MonoPIN.create(f.get('pin'));localStorage.setItem('mono-lock',JSON.stringify(record));lockRecord=record;}
   $('#actionDialog').close();render();notify(disable?'Код доступа отключён':'Код доступа сохранён');
  }catch(e){error.textContent=e.message||'Не удалось сохранить код. Попробуйте ещё раз.';error.hidden=false;}
  finally{b.disabled=false;}
 });bindPinInputs($('#actionBody'));
}
function lockApp(){if(!lockRecord)return;tourActive=false;$$('dialog[open]').forEach(d=>d.close());document.body.classList.add('offscreen-locked');$('#unlockPin').value='';const limit=MonoPIN.limit(lockRecord);$('#unlockPin').maxLength=limit;$('#unlockPin').dataset.pinLimit=limit;$('#unlockPin').pattern=limit===4?'[0-9]{4}':'[0-9]{4,12}';bindPinInputs($('#lockDialog'));$('#unlockError').hidden=true;if(!$('#lockDialog').open)$('#lockDialog').showModal();$('#unlockPin').focus({preventScroll:true});const legacy=$('#legacyUnlock');if(legacy)legacy.hidden=limit===4;}
let unlockAttempts=0,unlockUntil=0;
$('#lockDialog').addEventListener('cancel',e=>e.preventDefault());
$('#unlockForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');if(Date.now()<unlockUntil){$('#unlockError').textContent='Подождите 30 секунд перед следующей попыткой.';$('#unlockError').hidden=false;return;}b.disabled=true;try{if(await verifyPin($('#unlockPin').value)){unlockAttempts=0;$('#lockDialog').close();document.body.classList.remove('offscreen-locked');if(!state.settings.onboarded)startTour();}else{$('#unlockPin').value='';unlockAttempts++;if(unlockAttempts>=5){unlockUntil=Date.now()+30000;unlockAttempts=0;}$('#unlockError').textContent='Код не подошёл. Попробуйте ещё раз.';$('#unlockError').hidden=false;}}finally{b.disabled=false;}};
window.addEventListener('pagehide',()=>{cancelVoice();lockApp();});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelVoice();lockApp();}else renderHomeReminders();});
